check("opening freeze", !phased && !moved && !dmg, `ph=${V.rival.phase} x=${V.rival.x.toFixed(1)}`);
check("hint in through opening", !V.hintDone && V.hintFade===0 && V.hintIn>=V.HINT_IN_MS-20, `in=${V.hintIn} done=${V.hintDone} fade=${V.hintFade}`);

// tip blade
toMeasure();
V.attackEdge=true;
while(V.player.phase!=="active" && V.player.phase!=="recovery") V.update(STEP);
