function sliceFn(src, name) {
  const m = src.match(new RegExp("function " + name + "\\s*\\([^)]*\\)\\s*\\{"));
  if (!m) return "";
  const start = src.indexOf(m[0]);
  let i = start + m[0].length - 1, depth = 0;
  for (; i < src.length; i++) {
    if (src[i] === "{") depth++;
    else if (src[i] === "}") { depth--; if (depth === 0) return src.slice(start, i + 1); }
  }
  return "";
}
