function waitUntilWindow(){
  for(let i=0;i<60;i++){
    holdRival();
    if(V.player.phase==="recovery" && V.player.cut==="slash" && (V.RECOVERY - V.player.phaseT) <= V.SLASH_CANCEL_MS) return true;
    if(V.player.phase==="idle") return false;
    V.update(STEP);
  }
  return false;
}
