function sheetSrc(f){ return (V.poseBitmap(f)&&V.poseBitmap(f)._src)||""; }
function isCutSheet(f){ const src=sheetSrc(f); return /slash/.test(src) && !/windup/.test(src); }
function destNear(a,b,eps){
  return Math.abs(a.dx-b.dx)<eps && Math.abs(a.dy-b.dy)<eps && Math.abs(a.dw-b.dw)<eps && Math.abs(a.dh-b.dh)<eps && Math.abs(a.rot-b.rot)<0.002;
}
function holdCutPlant(label, plantDest){
  // v446: leftover full meter from longer Space connects made cancel-K super
  // (recovery 380; held~433) — empty-K plant read is the seat under test.
  V.player.meter = 0;
  V.player.superArmed = false;
  const d0 = plantDest || V.destRect(V.player);
  const tip0 = V.bladeTipX(V.player);
  check(label+" does not hop destRect off the cut", destNear(V.destRect(V.player), d0, 0.75), `dx=${(V.destRect(V.player).dx-d0.dx).toFixed(2)} dy=${(V.destRect(V.player).dy-d0.dy).toFixed(2)}`);
  check(label+" holds cut sheet at plant start", V.player.boltPhase==="startup" && isCutSheet(V.player), `bph=${V.player.boltPhase} src=${sheetSrc(V.player)}`);
  // Close-range dart is born on the rival and resolveBolt eats it the same tick.
  // Park them so birth can be sampled; player destRect/tip stay on the cut plant.
  V.rival.x = 1220;
  V.rival.stunT = 0;
  V.rival.guarding = false;
  V.rival.falling = false;
  V.rival.hp = V.MAX_HP;
  let popped=false, hopped=false, birthTip=null, birthX=null, birthFace=0, birthW=0, held=0;
  for(let i=0;i<20;i++){
    if(V.player.boltPhase!=="startup") break;
    if(!isCutSheet(V.player)) popped=true;
    if(!destNear(V.destRect(V.player), d0, 0.75)) hopped=true;
    holdRival();
    V.rival.x = 1220;
    V.rival.stunT = 0;
    V.rival.guarding = false;
    const tipBefore = V.bladeTipX(V.player);
    const had = !!V.bolt;
    V.update(STEP);
    held += STEP;
    if(!had && V.bolt){
      birthTip = tipBefore;
      birthX = V.bolt.x;
      birthFace = V.bolt.facing;
      birthW = V.bolt.w;
    }
  }
  check(label+" holds cut pose through 200ms", !popped && held>=180 && held<=220 && V.player.boltPhase==="recovery" && isCutSheet(V.player), `popped=${popped} held=${held} bph=${V.player.boltPhase} src=${sheetSrc(V.player)}`);
  check(label+" destRect plant holds through 200ms", !hopped, `dx=${(V.destRect(V.player).dx-d0.dx).toFixed(2)} dy=${(V.destRect(V.player).dy-d0.dy).toFixed(2)}`);
  const travel = V.BOLT_SPEED * (STEP/1000);
  const birth = birthFace>0 ? birthX - travel : birthX + birthW + travel;
  // v346: tip eases leftover sheathe→slash under holdCutFade during plant; birth is on
  // seated slash tip (not tip0 at cancel). Dart still births from live tip at spawn tick.
  check(label+" dart births from live cut tip", birthTip!=null && Math.abs(birth-birthTip)<3 && Math.abs(birthTip-V.bladeTipX(V.player))<8, `birth=${birth&&birth.toFixed(1)} live=${birthTip&&birthTip.toFixed(1)} plant=${tip0.toFixed(1)} now=${V.bladeTipX(V.player).toFixed(1)}`);
  const dartLive = !!V.bolt;
  const dartX0 = V.bolt ? V.bolt.x : null;
  let recPop=false, recHop=false, recHeld=0, dartBack=false;
  V.player.boltSuper = false; V.hitstopLeft = 0;
  for(let i=0;i<30;i++){
    if(V.player.boltPhase!=="recovery") break;
    if(!isCutSheet(V.player)) recPop=true;
    if(!destNear(V.destRect(V.player), d0, 0.75)) recHop=true;
    holdRival();
    V.rival.x = 1220;
    V.rival.stunT = 0;
    V.rival.guarding = false;
    V.update(STEP);
    recHeld += STEP;
    if(V.bolt && Math.abs(V.bolt.x - (V.bladeTipX(V.player) - (V.bolt.facing>0 ? 0 : V.bolt.w))) < 4) dartBack=true;
  }
  // v446: empty-K rec 280; leftover-full cancel can be super (380 + SUPER_STOP
  // hitstop wall-clock ~433). Pose hold is the seat — accept both.
  check(label+" holds cut pose through K recovery", !recPop && recHeld>=260 && recHeld<=450 && !V.player.boltPhase, `popped=${recPop} held=${recHeld} bph=${V.player.boltPhase} src=${sheetSrc(V.player)}`);
  check(label+" destRect plant holds through K recovery", !recHop, `dx=${(V.destRect(V.player).dx-d0.dx).toFixed(2)} dy=${(V.destRect(V.player).dy-d0.dy).toFixed(2)}`);
  check(label+" dart gone from blade after birth", dartLive && dartX0!=null && !dartBack, `live=${dartLive} x0=${dartX0} back=${dartBack} bolt=${!!V.bolt}`);
  check(label+" sheathes from the cut not idle pop", isCutSheet(V.player) && !V.player.boltPhase, `src=${sheetSrc(V.player)} bph=${V.player.boltPhase}`);
}
