function waitRivalBoltWindow(cut){
  const rec = cut==="golpe" ? V.GOLPE_RECOVERY : V.RECOVERY;
  for(let i=0;i<60;i++){
    holdYouDummy();
    const left = (V.rival.phase==="recovery" && V.rival.cut===cut) ? (rec - V.rival.phaseT) : 999;
    V.update(STEP);
    if(V.rival.boltPhase==="startup") return left;
    if(V.rival.phase==="idle" && !V.rival.boltPhase) return -1;
    if(cut==="slash" && V.rival.cut==="golpe") return -2;
    if(cut==="golpe" && V.rival.cut==="slash" && V.rival.phase==="startup") return -2;
  }
  return -1;
}
function armRivalSpecialCancel(cut){
  V.rival.linkBolt = true;
  V.rival.linkGolpe = false;
  V.rival.linkSlash = false;
  V.rival.boltCd = 0;
  V.rival.boltArmed = false;
  V.rival.boltPhase = "";
  V.rival.stamina = 100;
  V.rival.stamRegenT = 99999;
  V.rival.standGoal = 99999;
  if(cut) V.rival.cut = cut;
}

