check("throw pose is hurt sheet", thrownSheet===koSheet, `throw=${JSON.stringify(thrownSheet && {w:thrownSheet.w,footX:thrownSheet.footX})} ko=${JSON.stringify(koSheet && {w:koSheet.w,footX:koSheet.footX})}`);
