function fakeZone(){
  const c = new Set();
  return {
    classList: {
      add(x){ c.add(x); },
      remove(x){ c.delete(x); },
      contains(x){ return c.has(x); },
    },
  };
}
function padChord(zs, zslash){
  V.padDown("KeyS", 101, zs);
  V.padDown("Space", 102, zslash);
}
function padChordUp(){
  V.padUp(101);
  V.padUp(102);
}

