function waitLiveBolt(){
  for(let i=0;i<30;i++){
    holdSteelLane();
    V.update(STEP);
    if(V.bolt) return true;
  }
  return false;
}
function clashLiveBoltVs(def, cut){
  const atk = def===V.rival ? V.player : V.rival;
  holdSteelLane();
  def.phase = "active";
  def.phaseT = 16;
  const kind = cut || "slash";
  def.cut = kind;
  def.guarding = false;
  def.falling = false;
  def.stunT = 0;
  def.wantBlock = false;
  def.guardChoice = -1;
  atk.phase = "idle";
  atk.phaseT = 0;
  atk.guarding = false;
  atk.stunT = 0;
  atk.wantBlock = false;
  const hb = V.hitbox(def);
  const b = V.bolt;
  if(!hb || !b) return {ok:false, hb:!!hb, bolt:!!b};
  // Pin on the tip, away from the body, so resolveCuts cannot eat the steel first.
  if(def.facing > 0) b.x = hb.x + hb.w - b.w - 6;
  else b.x = hb.x + 6;
  b.y = hb.y + hb.h * 0.45 - b.h * 0.5;
  holdSteelLane();
  def.phase = "active";
  def.phaseT = 16;
  def.cut = kind;
  def.guarding = false;
  V.rival.guardChoice = -1;
  V.rival.wantBlock = false;
  V.rival.closing = false;
  V.update(STEP);
  return {ok:true, php:V.player.hp, rhp:V.rival.hp, fx:V.brasaFxKind, sfx:V.lastBoltConnectSfx, bolt:!!V.bolt, scale:V.brasaFxScale, stun:def.stunT, phase:def.phase};
}
function guardLiveBoltVs(def){
  holdSteelLane();
  def.phase = "idle";
  def.phaseT = 0;
  def.cut = "slash";
  def.guarding = true;
  def.wantBlock = true;
  def.falling = false;
  def.stunT = 0;
  def.guardChoice = 1;
  const atk = def===V.rival ? V.player : V.rival;
  atk.phase = "idle";
  atk.phaseT = 0;
  atk.guarding = false;
  atk.stunT = 0;
  atk.wantBlock = false;
  const bb = V.bodyAABB(def);
  const b = V.bolt;
  if(!bb || !b) return {ok:false, bb:!!bb, bolt:!!b};
  b.x = bb.x + (def.facing < 0 ? 8 : bb.w - b.w - 8);
  b.y = bb.y + bb.h * 0.45 - b.h * 0.5;
  holdSteelLane();
  def.phase = "idle";
  def.phaseT = 0;
  def.guarding = true;
  def.wantBlock = true;
  def.guardChoice = 1;
  V.rival.closing = false;
  V.update(STEP);
  return {ok:true, php:V.player.hp, rhp:V.rival.hp, fx:V.brasaFxKind, sfx:V.lastBoltConnectSfx, bolt:!!V.bolt, scale:V.brasaFxScale};
}


