function boxesOverlap(a,b){
  return !!(a && b && a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y);
}
function meatyLiveBoltVs(def, cut){
  const atk = def===V.rival ? V.player : V.rival;
  freezeRivalAI();
  freezeYouAI();
  V.player.hp = 100;
  V.rival.hp = 100;
  V.player.guarding = false;
  V.rival.guarding = false;
  V.player.stunT = 0;
  V.rival.stunT = 0;
  V.player.falling = false;
  V.rival.falling = false;
  V.player.pushT = 0;
  V.rival.pushT = 0;
  V.player.x = 400;
  V.rival.x = 700;
  def.phase = "active";
  def.phaseT = 16;
  def.cut = cut || "slash";
  def.wantBlock = false;
  def.guardChoice = -1;
  def.closing = false;
  def.guarding = false;
  atk.phase = "idle";
  atk.phaseT = 0;
  atk.wantBlock = false;
  atk.guarding = false;
  V.keepApart();
  def.phase = "active";
  def.phaseT = 16;
  def.cut = cut || "slash";
  def.guarding = false;
  const hb = V.hitbox(def);
  const bb = V.bodyAABB(def);
  const ba = V.bodyAABB(atk);
  const b = V.bolt;
  const meaty = !!(hb && boxesOverlap(hb, ba));
  if(!hb || !b || !meaty) return {ok:false, hb:!!hb, bolt:!!b, meaty, gap:V.bodyGap()};
  // Pin on the slasher body so the meaty cut and the dart share the frame.
  // Place on the incoming face so one tick of travel stays inside the AABB.
  if(b.vx >= 0) b.x = bb.x + 4;
  else b.x = bb.x + bb.w - b.w - 4;
  b.y = bb.y + bb.h * 0.45 - b.h * 0.5;
  const dartOn = boxesOverlap({x:b.x,y:b.y,w:b.w,h:b.h}, bb) || boxesOverlap({x:b.x,y:b.y,w:b.w,h:b.h}, hb);
  V.rival.guardChoice = -1;
  V.rival.wantBlock = false;
  V.rival.closing = false;
  V.rival.boltArmed = false;
  V.update(STEP);
  return {ok:true, php:V.player.hp, rhp:V.rival.hp, fx:V.brasaFxKind, sfx:V.lastBoltConnectSfx, bolt:!!V.bolt, stun:def.stunT, phase:def.phase, dartOn, meaty, atkHp:atk.hp, defHp:def.hp, gap:V.bodyGap()};
}

