function fireDartBirth(wantSuper){
  toMeasure();
  Math.random = () => 0.99;
  freezeRivalAI();
  V.player.x = 180;
  V.rival.x = 1100;
  V.player.phase = "idle";
  V.player.phaseT = 0;
  V.player.boltPhase = "";
  V.player.stunT = 0;
  V.player.guarding = false;
  V.player.falling = false;
  V.player.stamina = 100;
  V.player.stamRegenT = 99999;
  V.player.meter = wantSuper ? 100 : 0;
  V.player.boltSuper = false;
  V.boltEdge = true;
  V.update(STEP);
  if(wantSuper) drainHitstop();
  let born=null;
  for(let i=0;i<24;i++){
    V.rival.x = 1100;
    V.rival.gait = 0;
    V.rival.closing = false;
    const tipBefore = V.bladeTipX(V.player);
    const had = !!V.bolt;
    V.update(STEP);
    if(!had && V.bolt){
      born = { w:V.bolt.w, h:V.bolt.h, vx:V.bolt.vx, super:!!V.bolt.super, kind:V.bolt.kind, x:V.bolt.x, facing:V.bolt.facing, tip:tipBefore };
      break;
    }
  }
  return born;
}
const emptyBorn = fireDartBirth(false);
check("empty live dart size/speed",
  emptyBorn && emptyBorn.super===false && emptyBorn.w===V.BOLT_W && emptyBorn.h===V.BOLT_H && Math.abs(emptyBorn.vx)===V.BOLT_SPEED && emptyBorn.kind==="you",
  `born=${JSON.stringify(emptyBorn)} spd=${V.BOLT_SPEED} w=${V.BOLT_W}`
);
check("empty dart draw/speed unchanged in flight",
  emptyBorn && emptyBorn.super===false && emptyBorn.w===V.BOLT_W && emptyBorn.h===V.BOLT_H && Math.abs(emptyBorn.vx)===V.BOLT_SPEED && emptyBorn.kind==="you",
  `born=${JSON.stringify(emptyBorn)} spd=${V.BOLT_SPEED} w=${V.BOLT_W}`
);
const superBorn = fireDartBirth(true);
check("spent live dart size/speed",
  superBorn && superBorn.super===true && superBorn.w===V.BOLT_SUPER_W && superBorn.h===V.BOLT_SUPER_H && Math.abs(superBorn.vx)===V.BOLT_SUPER_SPEED && Math.abs(superBorn.vx)>V.BOLT_SPEED && superBorn.w>V.BOLT_W && superBorn.h>V.BOLT_H && V.player.meter===0 && V.BOLT_SUPER_DMG===28 && V.METER_MAX===100,
  `born=${JSON.stringify(superBorn)} m=${V.player.meter}`
);
check("super projectile larger-or-faster no range cheat",
  superBorn && superBorn.super===true && Math.abs(superBorn.vx)===V.BOLT_SUPER_SPEED && Math.abs(superBorn.vx)>V.BOLT_SPEED && superBorn.w===V.BOLT_SUPER_W && superBorn.h===V.BOLT_SUPER_H && superBorn.w>emptyBorn.w && superBorn.h>emptyBorn.h && Math.abs(superBorn.vx)>Math.abs(emptyBorn.vx) && V.player.meter===0 && V.BOLT_SUPER_DMG===28,
  `born=${JSON.stringify(superBorn)} empty=${JSON.stringify(emptyBorn)} m=${V.player.meter}`
);
const superTravel = Math.abs((superBorn && superBorn.vx) || 0) * (STEP/1000);
const superBirth = !superBorn ? 0 : (superBorn.facing > 0 ? superBorn.x - superTravel : superBorn.x + superBorn.w + superTravel);
