function raiseYouGuard(){
  freezeYouAI();
  freezeRivalAI();
  holdRivalStill();
  V.player.hp = 100;
  V.rival.hp = 100;
  V.player.stamina = 100;
  V.player.stamRegenT = 99999;
  V.player.guardBreakT = 0;
  V.player.stunT = 0;
  V.player.falling = false;
  V.player.boltPhase = "";
  V.player.reversal = false;
  V.player.cut = "slash";
  V.player.phase = "idle";
  V.player.phaseT = 0;
  V.keys.add("KeyS");
  V.update(STEP);
}

function fireReversalChord(){
  V.keys.add("KeyS");
  V.reversalEdge = true;
}

