function parkPushRoom(){
  freezeYouAI();
  freezeRivalAI();
  holdRivalStill();
  V.player.hp = 100;
  V.rival.hp = 100;
  V.player.stamina = 100;
  V.player.stamRegenT = 99999;
  V.player.guardBreakT = 0;
  V.player.stunT = 0;
  V.player.falling = false;
  V.player.boltPhase = "";
  V.player.reversal = false;
  V.player.cut = "slash";
  V.player.phase = "idle";
  V.player.phaseT = 0;
  V.player.pushT = 0;
  V.player.pushVel = 0;
  V.player.x = 520;
  V.rival.x = 880;
  V.player.facing = 1;
  V.rival.facing = -1;
  V.keys.clear();
  V.keepApart();
}

function raiseGuardInRoom(){
  parkPushRoom();
  V.keys.add("KeyS");
  V.update(STEP);
  V.player.stamina = 100;
  V.player.stamRegenT = 99999;
}

function waitPush(frames){
  for(let i=0;i<frames;i++){
    holdRivalStill();
    V.rival.standGoal = 99999;
    V.rival.closing = false;
    V.rival.gait = 0;
    V.update(STEP);
  }
}

