raiseGuardInRoom();
check("away setup facing right", V.player.guarding && V.player.facing>0 && V.awayWalkDir(V.player)===-1, `g=${V.player.guarding} face=${V.player.facing} away=${V.awayWalkDir(V.player)}`);
