const pbSpent = pbSt0 - pbSt1;
check("away+S while blocking spends stam", V.player.guarding && pbSpent>=V.PUSHBLOCK_STAM && pbSpent<=V.PUSHBLOCK_STAM+2 && V.player.pushT>0, `g=${V.player.guarding} spent=${pbSpent.toFixed(2)} pushT=${V.player.pushT} st0=${pbSt0.toFixed(2)} st=${pbSt1.toFixed(2)}`);
waitPush(12);
const pbDx = pbX0 - V.player.x;
const pbDg = V.absGap() - pbG0;
check("away+S while blocking pushes extra", pbDx>=pbHurt+8 && pbDx>=V.PUSHBLOCK_PX-30 && pbDx<=V.PUSHBLOCK_PX+20 && pbDg>=pbHurt && V.player.gait===0, `dx=${pbDx.toFixed(1)} dg=${pbDg.toFixed(1)} hurt=${pbHurt.toFixed(1)} px=${V.PUSHBLOCK_PX} gait=${V.player.gait} x0=${pbX0.toFixed(1)} x=${V.player.x.toFixed(1)}`);
