function parkRivalPushRoom(){
  toClose();
  freezeYouAI();
  freezeRivalAI();
  V.player.hp = 100;
  V.rival.hp = 100;
  V.player.stamina = 100;
  V.rival.stamina = 100;
  V.player.x = 480;
  V.rival.x = 820;
  V.player.facing = 1;
  V.rival.facing = -1;
  V.player.pushT = 0;
  V.rival.pushT = 0;
  V.player.pushVel = 0;
  V.rival.pushVel = 0;
  V.keepApart();
}

function armRivalPushblockAI(){
  parkRivalPushRoom();
  V.rival.phase = "idle";
  V.rival.phaseT = 0;
  V.rival.cut = "slash";
  V.rival.cutHit = false;
  V.rival.wantBlock = true;
  V.rival.guarding = true;
  V.rival.guardChoice = 1;
  V.rival.stamina = 100;
  V.rival.stamRegenT = 99999;
  V.rival.guardBreakT = 0;
  V.rival.pushT = 0;
  V.rival.pushVel = 0;
  V.rival.stunT = 0;
  V.rival.falling = false;
  V.rival.boltPhase = "";
  V.rival.boltCd = 99999;
  V.rival.throwCd = 99999;
  V.rival.revCd = 99999;
  V.rival.revArmed = -1;
  V.rival.wakeRevArmed = -1;
  V.rival.pbCd = 0;
  V.rival.pbArmed = 0;
  V.rival.reversal = false;
  V.rival.closing = false;
  V.rival.standWait = 0;
  V.rival.standGoal = 99999;
  V.rival.gait = 0;
  V.player.hp = 100;
  V.rival.hp = 100;
  V.player.guarding = false;
  V.player.stunT = 0;
  V.player.falling = false;
}

function holdMeatyForRivalPush(){
  const keepCut = V.player.cut==="golpe" ? "golpe" : "slash";
  const keepT = keepCut==="golpe" ? 90 : 150;
  holdYouSlashMeaty();
  V.player.cut = keepCut;
  V.player.phase = "startup";
  V.player.phaseT = keepT;
  V.player.cutHit = false;
  V.player.clashRec = false;
  V.player.reversal = false;
  V.player.boltPhase = "";
  V.rival.boltCd = 99999;
  V.rival.throwCd = 99999;
  V.rival.revCd = 99999;
  V.rival.revArmed = -1;
  V.rival.wantBlock = true;
  V.rival.guarding = true;
  V.rival.guardChoice = 1;
  V.rival.gait = 0;
  V.rival.closing = false;
  V.rival.standGoal = 99999;
}

function waitRivalPush(frames){
  for(let i=0;i<frames;i++){
    holdMeatyForRivalPush();
    V.update(STEP);
  }
}

