function liveConnectingRivalPush(cut){
  armRivalPushblockAI();
  V.player.phase = "idle";
  V.player.cut = "slash";
  V.player.phaseT = 0;
  V.player.cutHit = false;
  V.player.guarding = false;
  V.player.stunT = 0;
  V.player.falling = false;
  V.player.boltPhase = "";
  V.rival.pbArmed = 1;
  V.rival.pbCd = 0;
  V.rival.revArmed = -1;
  V.rival.revCd = 99999;
  V.rival.wantBlock = true;
  V.rival.guarding = true;
  V.rival.guardChoice = 1;
  Math.random = () => 0;
  const x0 = V.rival.x;
  const st0 = V.rival.stamina;
  V.startAttack(V.player, cut==="golpe" ? "golpe" : undefined);
  let blocked=false, hit=false, pb=false, whiff=false;
  for(let i=0;i<90;i++){
    Math.random = () => 0;
    V.rival.wantBlock = true;
    V.rival.guardChoice = 1;
    V.rival.revArmed = -1;
    V.rival.revCd = 99999;
    V.rival.boltCd = 99999;
    V.rival.throwCd = 99999;
    V.rival.closing = false;
    V.rival.standGoal = 99999;
    V.rival.gait = 0;
    V.player.guarding = false;
    V.player.stunT = 0;
    V.player.falling = false;
    V.player.boltPhase = "";
    V.keys.clear();
    const ph0 = V.player.phase;
    V.update(STEP);
    if(V.rival.pushT>0 && (st0-V.rival.stamina)>=V.PUSHBLOCK_STAM-2) pb=true;
    if(V.player.cutHit && V.rival.hp===100) blocked=true;
    if(V.rival.hp<100) hit=true;
    if(ph0==="active" && V.player.phase==="recovery" && !V.player.cutHit) whiff=true;
    if(V.hitstopLeft>0) drainHitstop();
    if(V.player.phase==="idle" && i>5) break;
  }
  for(let i=0;i<20;i++){
    V.rival.wantBlock = true;
    V.rival.guardChoice = 1;
    V.rival.revCd = 99999;
    V.rival.revArmed = -1;
    V.update(STEP);
    if(V.rival.pushT<=0 && V.hitstopLeft<=0 && V.player.phase==="idle") break;
  }
  return { blocked, hit, pb, whiff, dx: V.rival.x-x0, spent: st0-V.rival.stamina, php: V.player.hp, rhp: V.rival.hp, sfx: V.lastPushblockSfx, g: V.rival.guarding };
}
