function holdWakeSample(){
  holdRivalNoGrab();
  V.rival.wantBlock = false;
  V.rival.guardChoice = -1;
  V.rival.guarding = false;
  V.rival.gait = 0;
  V.rival.closing = false;
  V.player.guarding = false;
  V.player.phase = "idle";
  V.player.phaseT = 0;
  V.player.cut = "slash";
  V.hitstopLeft = 0;
}
function isHurtSheet(f){ return /hurt/.test(sheetSrc(f)); }

