function chestXY(f){
  const bb=V.bodyAABB(f);
  return {x: bb.x + bb.w*0.5, y: bb.y + bb.h*0.28};
}

function overlapsBox(a,b){
  return !!(a && b && a.x < b.x+b.w && a.x+a.w > b.x && a.y < b.y+b.h && a.y+a.h > b.y);
}
function plantJustConnect(atk, def, kind){
  const lunge = kind==="golpe" ? V.GOLPE_LUNGE_PX : V.LUNGE_PX;
  atk.cut = kind==="golpe" ? "golpe" : "slash";
  atk.phase = "active";
  atk.phaseT = 20;
  atk.cutHit = false;
  atk.guarding = false;
  atk.stunT = 0;
  atk.boltPhase = "";
  def.guarding = false;
  def.stunT = 0;
  def.phase = "idle";
  def.phaseT = 0;
  def.boltPhase = "";
  if (atk.kind==="you") atk.x = def.x - 420;
  else atk.x = def.x + 420;
  atk.x += atk.facing * lunge;
  let ok=false;
  for(let i=0;i<120;i++){
    if (overlapsBox(V.hitbox(atk), V.bodyAABB(def))) { ok=true; break; }
    atk.x += atk.facing * 4;
  }
  return ok;
}

