function poseTipWorldX(f, tipX){
  // tipX under plant fades: bladeTipX eases under link/clash fades, so do not
  // recover scale from bladeTipX (that baked the ease into slashTipX). Use
  // destRect sheet scale + marker tipX instead.
  const r = V.destRect(f);
  const sheet = V.poseSheet(f);
  const sc = sheet && sheet.w ? r.dw / sheet.w : 0;
  return r.dx + tipX * sc;
}
function slashTipX(f){ return poseTipWorldX(f, 991); }
function knifeTipX(f){ return poseTipWorldX(f, 268); }
