function captureConnectingRivalDust(cut, forcePb){
  armRivalPushblockAI();
  toClose();
  V.plantDust.splice(0);
  V.player.phase = "idle";
  V.player.cut = "slash";
  V.player.phaseT = 0;
  V.player.cutHit = false;
  V.player.guarding = false;
  V.player.stunT = 0;
  V.player.falling = false;
  V.player.boltPhase = "";
  V.rival.pbArmed = forcePb ? 1 : -1;
  V.rival.pbCd = 0;
  V.rival.revArmed = -1;
  V.rival.revCd = 99999;
  V.rival.wantBlock = true;
  V.rival.guarding = true;
  V.rival.guardChoice = 1;
  V.rival.stamina = 100;
  Math.random = () => (forcePb ? 0 : 0.99);
  const x0 = V.rival.x;
  const st0 = V.rival.stamina;
  const aabb0 = V.bodyAABB(V.rival);
  V.startAttack(V.player, cut==="golpe" ? "golpe" : undefined);
  let blocked=false, pb=false, saw=false;
  let shoveN=0, blockN=0, shovePow=0, sfx="";
  for(let i=0;i<90;i++){
    Math.random = () => (forcePb ? 0 : 0.99);
    V.rival.wantBlock = true;
    V.rival.guardChoice = 1;
    V.rival.revArmed = -1;
    V.rival.revCd = 99999;
    V.rival.boltCd = 99999;
    V.rival.throwCd = 99999;
    V.rival.closing = false;
    V.rival.standGoal = 99999;
    V.rival.gait = 0;
    V.player.guarding = false;
    V.player.stunT = 0;
    V.player.falling = false;
    V.player.boltPhase = "";
    V.keys.clear();
    V.update(STEP);
    if(V.player.cutHit && V.rival.hp===100) blocked=true;
    if(V.lastPushblockSfx==="pushblock" && V.rival.pushT>0 && (st0-V.rival.stamina)>=V.PUSHBLOCK_STAM-2) pb=true;
    // Capture only on this connect — leftover lastPushblockSfx must not trip saw.
    if(V.player.cutHit && !saw){
      saw=true;
      const stamps=(V.plantDust||[]).filter(p=>!p.speck && p.homeYou===false);
      shoveN=stamps.filter(p=>p.shove).length;
      blockN=stamps.filter(p=>!p.shove && Math.abs((p.power||0)-1)<0.01).length;
      shovePow=stamps.filter(p=>p.shove).reduce((m,p)=>Math.max(m,p.power||0),0);
      sfx=V.lastPushblockSfx;
      blocked = V.rival.hp===100;
      pb = sfx==="pushblock" && shoveN>0;
    }
    if(V.hitstopLeft>0) drainHitstop();
    if(saw && V.player.phase==="idle" && i>5) break;
  }
  return { blocked, pb, shoveN, blockN, shovePow, sfx, dx: V.rival.x-x0, dy: V.bodyAABB(V.rival).y-aabb0.y };
}

