function armMidStrideSheatheRaise(){
  freezeYouAI(); freezeRivalAI();
  holdRivalStill();
  V.keys.clear();
  V.hitstopLeft=0; V.openLeft=0;
  V.player.x=400; V.rival.x=900;
  V.player.facing=1; V.rival.facing=-1;
  V.player.phase="idle"; V.player.phaseT=0; V.player.cut="slash";
  V.player.stunT=0; V.player.falling=false; V.player.thrownT=0; V.player.throwInvulnT=0;
  V.player.boltPhase=""; V.player.boltHoldCut=false; V.player.boltSuper=false;
  V.player.guarding=false; V.player.guardPoseK=0; V.player.guardBreakT=0;
  V.player.feintT=0; V.player.reversal=false;
  V.player.linkPlant=false; V.player.clashPlant=false; V.player.holdCutPlant=false;
  V.player.linkSheathe=0; V.player.telegraph=false;
  V.player.stamina=100; V.player.meter=0; V.player.hp=100;
  V.player.sheatheT = V.SHEATHE_MS; // clash/tech idle sheathe mid-fade
  V.player.gait=1; V.player.walkT = V.WALK_STEP_MS * 0.5; // mid-pass so walkSheetK is live
  V.player.walkSettleT=0; V.player.walkRiseT=V.WALK_SETTLE_MS; V.player.walkPlanted=true;
  V.player.walkFadeHold = 0.9; // capture mid-stride hold before raise
  V.keys.add("KeyD");
  V.keepApart();
}

// live: mid-stride sheathe Space keeps walkFadeHold under link raise (not idle dump)
