{
  const hold0 = V.player.walkFadeHold;
  const aabb0 = V.bodyAABB(V.player);
  const sf0 = V.sheatheFade(V.player);
  V.attackEdge = true;
  V.update(STEP);
  freezeRivalAI(); // do not freezeYouAI — that snaps startup back to idle
  let lwOk = V.player.cut==="slash" && V.player.phase==="startup" && V.player.linkPlant===true && V.player.telegraph===false && V.player.walkFadeHold>0.02 && V.linkPlantFade(V.player)>0.02 && /windup/.test(sheetSrc(V.player));
  check("link plant walk-in pose leftover live Space arms", lwOk && hold0>0.5 && sf0>0.5, `ok=${lwOk} cut=${V.player.cut} ph=${V.player.phase} lp=${V.player.linkPlant} tel=${V.player.telegraph} hold=${V.player.walkFadeHold} lf=${V.linkPlantFade(V.player)} src=${sheetSrc(V.player)} hold0=${hold0} sf0=${sf0}`);
  check("link plant walk-in pose leftover live poseBitmap windup not idle dump", /windup/.test(sheetSrc(V.player)) && V.player.walkFadeHold>0.02 && !/throw_knife/.test(sheetSrc(V.player)), `src=${sheetSrc(V.player)} hold=${V.player.walkFadeHold}`);
  let midOk=true, sawMid=false, maxHop=0, aabbOk=true, holdLive=false;
  const aabbY0 = aabb0.y;
  for (let i=0;i<8;i++){
    freezeRivalAI();
    V.player.stunT=0; V.player.falling=false; V.hitstopLeft=0;
    const lf = V.linkPlantFade(V.player);
    if (V.player.linkPlant && V.player.phase==="startup" && lf > 0.05 && lf < 0.95) {
      sawMid = true;
      if (V.player.walkFadeHold <= 0.02) midOk = false;
      else holdLive = true;
      if (!/windup/.test(sheetSrc(V.player)) || /throw_knife/.test(sheetSrc(V.player))) midOk = false;
    }
    const dy0 = V.destRect(V.player).dy;
    V.update(STEP);
    maxHop = Math.max(maxHop, Math.abs(V.destRect(V.player).dy - dy0));
    if (Math.abs(V.bodyAABB(V.player).y - aabbY0) > 0.05) aabbOk = false;
  }
  check("link plant walk-in pose leftover live mid raise keeps walkFadeHold", sawMid && midOk && holdLive, `saw=${sawMid} ok=${midOk} holdLive=${holdLive} hold=${V.player.walkFadeHold} lf=${V.linkPlantFade(V.player)} src=${sheetSrc(V.player)}`);
  check("link plant walk-in pose leftover live AABB planted", aabbOk, `aabbOk=${aabbOk}`);
  check("link plant walk-in pose leftover live destRect no sheet hop", maxHop < 3.5, `hop=${maxHop.toFixed(3)}`);
}

