V.keys.add("KeyS");
freezeRivalAI(); V.update(STEP);
V.player.guardPoseK = 0.2;
const rvTip0 = V.bladeTipX(V.player);
const rvR0 = V.destRect(V.player);
const rvEdge0 = V.player.facing>0 ? rvR0.dx+rvR0.dw-8 : rvR0.dx+8;
const rvWu0 = rvR0.dx + 359 * (rvR0.dw/1186);
const rvDid = V.startReversal(V.player);
const rvArmTip = V.bladeTipX(V.player);
const rvArmRpf = V.reversalPlantFade(V.player);
const rvArmRp = V.reversalPlanting(V.player);
const rvArmPt = V.player.phaseT|0;
