// live: slash / golpe / throw active stamp arms scrape with grit (once)
function liveActivePlantScrape(label, startFn, expectCut){
  toMeasure();
  freezeYouAI(); freezeRivalAI();
  V.mode = "play";
  V.player.x=360; V.rival.x=980; V.openLeft=0; V.hitstopLeft=0;
  Object.assign(V.player,{phase:"idle",phaseT:0,boltPhase:"",stunT:0,guarding:false,falling:false,feintT:0,sheatheT:0,cutRecBreathT:0,guardPoseK:0,walkSettleT:0,walkFadeHold:0,walkRiseT:0,gait:0,walkT:0,walkPlanted:false,reversal:false,telegraph:false,linkPlant:false,riposte:false,riposteArmed:false,hp:100,stamina:100,facing:1});
  Object.assign(V.rival,{phase:"idle",phaseT:0,boltPhase:"",stunT:0,guarding:false,falling:false,gait:0,closing:false,hp:100,stamina:100,facing:-1,x:980});
  V.keys.clear();
  V.lastPlantSfx="";
  V.plantDust.splice(0);
  const aabb0=V.bodyAABB(V.player);
  const dest0=V.destRect(V.player);
  startFn();
  let armed=false, dusted=false, cut="", fires=0, lastPh="", reArmed=false, destOk=true, aabbOk=true, prevDy=null;
  for(let i=0;i<80;i++){
    // do NOT freezeYouAI here — it resets phase to idle and cancels the cut
    freezeRivalAI();
    V.openLeft=0; V.hitstopLeft=0; V.rival.x=980; V.rival.gait=0; V.rival.phase="idle"; V.rival.closing=false;
    V.keys.clear();
    const d0=V.plantDust.filter(p=>!p.speck&&!p.shove&&p.homeYou).length;
    const ph0=V.player.phase;
    V.update(STEP);
    const d1=V.plantDust.filter(p=>!p.speck&&!p.shove&&p.homeYou).length;
    if(ph0!=="active" && V.player.phase==="active"){
      dusted = d1>d0;
      cut = V.player.cut;
      if(V.lastPlantSfx==="plant") armed=true;
      fires++;
      // clear mid-active so a per-frame scrape would re-arm and fail
      V.lastPlantSfx="";
      // juice-only: AABB planted (y/h) vs idle; destRect.dy leftover sample vs prior mid-lunge frame
      const aa=V.bodyAABB(V.player);
      if(Math.abs(aa.y-aabb0.y)>=8 || Math.abs(aa.h-aabb0.h)>=8) aabbOk=false;
      prevDy=V.destRect(V.player).dy;
    } else if(V.player.phase==="active" && lastPh==="active"){
      // still active: scrape must not re-arm every frame
      if(V.lastPlantSfx==="plant") reArmed=true;
      const dy=V.destRect(V.player).dy;
      if(prevDy!=null && Math.abs(dy-prevDy)>=2.2) destOk=false;
      prevDy=dy;
    }
    lastPh=V.player.phase;
    if(V.player.phase==="recovery" || V.player.phase==="idle") break;
  }
  check(`lunge/active plant grit audio sync leftover live ${label} scrape`, armed && dusted && cut===expectCut && fires===1 && !reArmed && aabbOk && destOk, `armed=${armed} dust=${dusted} cut=${cut} expect=${expectCut} fires=${fires} reArmed=${reArmed} aabbOk=${aabbOk} destOk=${destOk} sfx=${V.lastPlantSfx} ph=${V.player.phase}`);
}

liveActivePlantScrape("slash", ()=>{ V.startAttack(V.player); return V.player.phase==="startup" && V.player.cut==="slash"; }, "slash");
liveActivePlantScrape("golpe", ()=>{ V.startAttack(V.player,"golpe"); return V.player.phase==="startup" && V.player.cut==="golpe"; }, "golpe");
liveActivePlantScrape("throw", ()=>{ const t=V.startThrow(V.player); return !!t && V.player.phase==="startup" && V.player.cut==="throw"; }, "throw");

