// live: whiff keeps scrape+grit; connect suppresses ghost scrape
// lastPlantSfx is sticky (walk-stop / opening). Clear it each tick so the
// assert only sees scrape armed on the startup→active/connect transition.
function liveLungeScrapeCull(label, startFn, connect){
  toMeasure();
  freezeRivalAI();
  V.mode = "play";
  V.player.x=420; V.rival.x=connect?560:1100; V.openLeft=0; V.hitstopLeft=0;
  Object.assign(V.player,{phase:"idle",phaseT:0,boltPhase:"",stunT:0,guarding:false,falling:false,feintT:0,sheatheT:0,cutRecBreathT:0,guardPoseK:0,walkSettleT:0,walkFadeHold:0,walkRiseT:0,gait:0,walkT:0,walkPlanted:false,lungePlantSfx:false,reversal:false,telegraph:false,linkPlant:false,riposte:false,riposteArmed:false,hp:100,stamina:100,facing:1,cutHit:false});
  Object.assign(V.rival,{phase:"idle",phaseT:0,boltPhase:"",stunT:0,guarding:false,falling:false,gait:0,walkT:0,walkRiseT:0,walkPlanted:false,walkFadeHold:0,closing:false,hp:100,stamina:100,facing:-1,x:connect?560:1100});
  V.keys.clear();
  V.lastPlantSfx="";
  V.plantDust.splice(0);
  // clear opening grit
  for(let i=0;i<8;i++){ freezeRivalAI(); V.rival.gait=0; V.rival.walkPlanted=false; V.rival.closing=false; V.update(STEP); }
  V.plantDust.splice(0);
  V.lastPlantSfx="";
  V.player.gait=0; V.player.walkPlanted=false; V.player.walkRiseT=0; V.player.walkFadeHold=0;
  V.rival.gait=0; V.rival.walkPlanted=false; V.rival.walkRiseT=0; V.rival.walkFadeHold=0; V.rival.closing=false;
  startFn();
  let saw=false, ghost=false, whiffOk=false;
  for(let i=0;i<40;i++){
    freezeRivalAI();
    if(!connect){ V.rival.x=1100; V.rival.phase="idle"; V.rival.gait=0; V.rival.closing=false; }
    V.openLeft=0;
    V.rival.gait=0; V.rival.walkPlanted=false; V.rival.closing=false;
    const ph0=V.player.phase;
    // Same-tick scrape only — sticky lastPlantSfx from walk-stop must not count.
    V.lastPlantSfx="";
    V.update(STEP);
    if(ph0==="startup" && (V.player.phase==="active" || V.player.phase==="recovery" || V.hitstopLeft>0)){
      saw=true;
      const sLive = V.plantDust.filter(p=>!p.speck&&!p.shove&&p.homeYou&&!p.punch).length;
      const scraped = V.lastPlantSfx==="plant";
      if(connect){
        // connect should NOT scrape for culled lunge (impacto owns ear)
        ghost = scraped && sLive===0 && V.hitstopLeft>0;
      } else {
        whiffOk = scraped && sLive>0 && V.hitstopLeft<=0;
      }
      break;
    }
  }
  return {saw, ghost, whiffOk, cutHit:!!V.player.cutHit, hs:V.hitstopLeft, last:V.lastPlantSfx};
}

{
  // Wire a tiny play spy if bar harness exposes Audio plays — fall back to lastPlantSfx.
  const w = liveLungeScrapeCull("whiff", ()=>{ V.attackEdge=true; }, false);
  check("lunge plant scrape knock cull leftover live whiff keeps scrape+grit", w.saw && w.whiffOk && !w.ghost, JSON.stringify(w));
}
{
  const c = liveLungeScrapeCull("connect", ()=>{ V.attackEdge=true; }, true);
  check("lunge plant scrape knock cull leftover live connect suppresses ghost scrape", c.saw && !c.ghost && c.hs>0, JSON.stringify(c));
}
{
  const g = liveLungeScrapeCull("golpe-connect", ()=>{ V.golpeEdge=true; }, true);
  check("lunge plant scrape knock cull leftover live golpe connect suppresses ghost scrape", g.saw && !g.ghost && g.hs>0, JSON.stringify(g));
}

