{
  // Live: measure-range empty K recovery with dart already gone → punish during recovery
  function bootP(){
    V.resetRound(); V.mode="play"; V.openLeft=0; V.hitstopLeft=0; V.keys.clear();
    V.player.x=400; V.rival.x=871;
    V.rival.throwCd=99999; V.rival.revCd=99999; V.rival.feintCd=99999; V.rival.pbCd=99999; V.rival.boltCd=99999;
    V.rival.aiBaitT=0; V.rival.aiRetreatT=0; V.rival.aiResetT=0; V.rival.aiMidApproachT=0;
    for (let i=0;i<3;i++) V.update(STEP);
  }
  bootP();
  // Force abs ~120 measure by nudging rival if needed
  V.player.x=400;
  let lo=450, hi=1100, best=871;
  for (let k=0;k<24;k++){
    const mid=(lo+hi)/2; V.rival.x=mid;
    const a=V.absGap();
    if (Math.abs(a-120)<2){ best=mid; break; }
    if (a<120) lo=mid; else hi=mid; best=mid;
  }
  V.rival.x=best;
  V.bolt=null;
  V.player.boltPhase="recovery"; V.player.boltT=0; V.player.boltSuper=false;
  V.player.phase="idle"; V.player.gait=0; V.player.stunT=0;
  V.rival.phase="idle"; V.rival.standWait=0; V.rival.standGoal=0; V.rival.closing=false;
  const _r=Math.random; Math.random=()=>0.5; // mid standoff if fallen through; punish path ignores rand
  let saw=null;
  for (let i=0;i<30;i++){
    const br=V.rival.phase;
    V.update(STEP); V.hitstopLeft=0;
    if (br==="idle" && V.rival.phase==="startup"){
      saw={i, cut:V.rival.cut, pb:V.player.boltPhase, abs:V.absGap()};
      break;
    }
  }
  Math.random=_r;
  check("dart recovery punish leftover live empty K in-rec", !!(saw && saw.pb==="recovery" && (saw.cut==="slash"||saw.cut==="golpe")), `saw=${JSON.stringify(saw)}`);
  // Live: while you-dart still live, AI must NOT rush punish (boltIncoming freeze).
  // Keep bolt past the rival hurtbox (already cleared them) so resolveBolt does not eat it.
  bootP();
  V.player.x=400; V.rival.x=best;
  V.player.boltPhase="recovery"; V.player.boltT=0; V.player.phase="idle"; V.player.stunT=0;
  V.rival.phase="idle"; V.rival.standWait=0; V.rival.standGoal=0; V.rival.closing=false;
  Math.random=()=>0.5;
  let rushed=false; let sawLive=false;
  for (let i=0;i<12;i++){
    // Re-seat a live you-dart each tick so flight/cull cannot clear the freeze gate.
    V.bolt={ x:V.rival.x + 120, y:400, w:58, h:13, vx:0, facing:1, kind:"you", super:false };
    if (V.bolt && V.bolt.kind==="you") sawLive=true;
    const br=V.rival.phase;
    V.update(STEP); V.hitstopLeft=0;
    if (br==="idle" && V.rival.phase==="startup"){ rushed=true; break; }
  }
  Math.random=_r;
  check("dart recovery punish leftover live dart freeze", !rushed && sawLive, `rushed=${rushed} sawLive=${sawLive}`);
  // Live: Space recovery punish still works
  bootP();
  V.player.x=400; V.rival.x=best;
  V.bolt=null; V.player.boltPhase="";
  V.player.cut="slash"; V.player.phase="recovery"; V.player.phaseT=40; V.player.stunT=0;
  V.rival.phase="idle"; V.rival.standWait=0; V.rival.standGoal=0; V.rival.closing=false;
  Math.random=()=>0.5;
  let spaceSaw=null;
  for (let i=0;i<30;i++){
    const br=V.rival.phase;
    V.update(STEP); V.hitstopLeft=0;
    if (br==="idle" && V.rival.phase==="startup"){ spaceSaw={i,cut:V.rival.cut}; break; }
  }
  Math.random=_r;
  check("dart recovery punish leftover live Space recovery kept", !!(spaceSaw && (spaceSaw.cut==="slash"||spaceSaw.cut==="golpe")), `saw=${JSON.stringify(spaceSaw)}`);
  check("dart recovery punish leftover live frames locked", V.BOLT_STARTUP===200 && V.BOLT_RECOVERY===280 && V.BOLT_SUPER_RECOVERY===380 && V.BOLT_AI_CD===1800 && V.AI_MID_DART===0.72);
}
